<div role="main" aria-label="{{.Title}}" class="page-content soda-page soda-auth soda-native-forms user signin{{if .LinkAccountMode}} icon{{end}}" data-signed="{{if .IsSigned}}true{{else}}false{{end}}">
	<div class="ui container soda-page-container soda-form-layout">
		{{if and (not .DisableRegistration) (not .LinkAccountMode)}}{{template "custom/soda/page_intro" dict "TitleID" "soda-form-title" "Title" (ctx.Locale.Tr "auth.create_new_account") "Description" "A shared home for your code and ideas." "Eyebrow" "Join Soda Forge" "Artwork" "signup-papercraft.png" "Class" "soda-form-story"}}{{else}}{{template "custom/soda/page_intro" dict "TitleID" "soda-form-title" "Title" .Title "Description" "" "Eyebrow" "" "Artwork" "" "Class" "soda-form-story"}}{{end}}
<div class="soda-form-content">
			{{template "user/auth/signup_inner" .}}
		</div>
{{template "base/head" .}}
<div role="main" aria-label="{{.Title}}" class="page-content soda-page soda-auth soda-native-forms user signin{{if .LinkAccountMode}} icon{{end}}" data-signed="{{if .IsSigned}}true{{else}}false{{end}}">
	<div class="ui middle very relaxed page grid">
		<div class="column tw-flex tw-flex-col tw-gap-4 tw-max-w-2xl tw-m-auto">
			{{if and (not .DisableRegistration) (not .LinkAccountMode)}}<img class="tw-mx-auto" src="{{AssetUrlPrefix}}/soda/forgejo/signup-papercraft.png" width="180" height="120" alt="">{{end}}
			{{template "user/auth/signup_inner" .}}
		</div>

